<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import Composer from './Composer.vue';
import ConversationLesson from './ConversationLesson.vue';
import LiveLesson from './LiveLesson.vue';
import { liveRequest } from './live';
import type { LiveSession } from './live';
import StudentHome from './StudentHome.vue';
import LearningStatus from './LearningStatus.vue';
import ClassroomProgress from './ClassroomProgress.vue';
import { statusCatalog } from './statusCatalog';
import { chapters, chapterOf, historicalRecords, learnerName, spaceName } from './data';
import type { RecordItem } from './data';
import { state, startLesson, sessionRecord, requestReview, touchSession, orderedSessions, scriptedPreview, classroomIsCurrent } from './state';
import type { Session } from './state';
import { chapterCounts, displayRequirementState, hasReference } from './home';
const props=defineProps<{parent:boolean;page:string}>();
const route=useRoute(),router=useRouter();
const page=computed(()=>{const name=props.page||(props.parent?'overview':'home');return props.parent&&!['overview','status','record','consult','account'].includes(name)?'unavailable':name;});
const child=computed(()=>props.parent?state.parentChild:'S0001');
const space=computed({get:()=>props.parent?state.parentSpace:state.studentSpace,set:(v:string)=>{if(props.parent)state.parentSpace=v;else state.studentSpace=v;}});
const q=(key:string,otherwise='')=>String(route.query[key]||otherwise);
const chapter=computed(()=>chapterOf(q('chapter','fractions')));
const notice=ref(''),reviewOpen=ref(false),reviewReason=ref('');
const personalSessions=computed(()=>orderedSessions(state.sessions.filter(s=>s.learner===child.value&&s.space===space.value)));
const current=computed(()=>personalSessions.value.find(s=>s.id===q('id')));
const pendingCheck=computed(()=>!props.parent&&state.sessions.find(s=>s.learner==='S0001'&&s.status==='check'));
const live=computed(()=>personalSessions.value.map(sessionRecord));
const history=computed(()=>child.value==='S0001'&&state.home.reference==='none'?[]:historicalRecords(child.value,space.value));
const record=computed(()=>[...live.value,...history.value].find(r=>r.id===q('id')));
const segment=computed(()=>current.value?chapterOf(current.value.chapter)?.segments[current.value.segment]:undefined);
const currentChapter=computed(()=>current.value?chapterOf(current.value.chapter):undefined);
const continuingLegacy=computed(()=>!props.parent&&!scriptedPreview&&page.value==='lesson'&&current.value?.chapter==='fractions'&&!current.value.real&&current.value.status==='learning');
const conversationPage=computed(()=>!props.parent&&page.value==='lesson'&&(current.value?.real||continuingLegacy.value));
const scope=computed(()=>`${props.parent?'parent-P0001':'student'}:${child.value}:${space.value}:${page.value==='lesson'?q('id'):page.value==='record'?q('id'):q('chapter','general')}`);
const nav=computed(()=>props.parent?[['overview','概况'],['consult','咨询']]:[['home','首页'],['status','学习情况'],['materials','教材'],['records','学习记录']]);
const navActive=computed(()=>['lesson','prepare','result'].includes(page.value)?'home':page.value==='record'?'records':page.value==='status'&&props.parent?'overview':page.value);
const mainElement=ref<HTMLElement>();
const creatingReal=ref(false);
async function beginReal(previous?:Session){
 if(props.parent||space.value!=='school'||creatingReal.value)return;
 if(pendingCheck.value){go('lesson',{id:pendingCheck.value.id});notice.value='先结束当前检查，再开启真实对话。';return;}
 if(previous?.realSuccessor&&state.sessions.some(s=>s.id===previous.realSuccessor&&s.real)){void router.replace({path:'/lesson',query:{id:previous.realSuccessor}});return;}
 creatingReal.value=true;
 try{const result=await liveRequest<LiveSession>('sessions',{});const s:Session={id:result.id,real:true,learner:child.value,space:space.value,chapter:'fractions',segment:0,status:'learning',answer:'',submitted:false,endedReason:'',date:new Date().toISOString().slice(0,10),updatedAt:Date.now()};state.sessions.unshift(s);if(previous){previous.realSuccessor=s.id;const oldDraft=state.drafts[`student:${previous.learner}:${previous.space}:${previous.id}`];if(oldDraft)state.drafts[`real:${s.id}`]=oldDraft;void router.replace({path:'/lesson',query:{id:s.id}});}else go('lesson',{id:s.id});}
 catch(e){notice.value=(e as Error).message;}finally{creatingReal.value=false;}
}
const scrollPositions=new Map<string,number>();
watch(()=>route.fullPath,async(to,from)=>{const scrollTop=mainElement.value?.scrollTop||0;scrollPositions.set(from,scrollTop);await nextTick();if(mainElement.value)mainElement.value.scrollTop=scrollPositions.get(to)||0;});
watch(()=>[page.value,q('id')],()=>{if(!props.parent&&page.value==='lesson'&&current.value&&current.value.status!=='ended')touchSession(current.value);},{immediate:true});
watch(()=>current.value?.answer,()=>{if(!props.parent&&current.value?.status==='check')touchSession(current.value);});
function go(to:string,query:Record<string,string>={}){if(pendingCheck.value&&to!=='lesson'){notice.value='先继续或结束当前检测，再开始其他活动。';return;}void router.push({path:`/${to}`,query});}
function back(){if(q('from'))void router.push(q('from'));else go(props.parent?'overview':'records');}
function filter(key:string,value:string){void router.replace({query:{...route.query,[key]:value,p:'1'}});}
function selectSpace(e:Event){if(pendingCheck.value){notice.value='当前检测尚未结束，请先返回处理。';return;}space.value=(e.target as HTMLSelectElement).value;void router.replace({path:props.parent?'/overview':page.value==='status'?'/status':'/home'});}
function selectChild(e:Event){state.parentChild=(e.target as HTMLSelectElement).value;void router.replace({path:'/overview'});}
watch(()=>route.fullPath,()=>{notice.value='';reviewOpen.value=false;reviewReason.value='';});
watch(()=>[page.value,current.value?.conversation,current.value?.real],()=>{if(!props.parent&&(current.value?.conversation||current.value?.real)&&['prepare','result'].includes(page.value))void router.replace({path:'/lesson',query:{id:current.value!.id}});},{immediate:true});
watch(()=>route.fullPath,()=>{if(pendingCheck.value&&(page.value!=='lesson'||q('id')!==pendingCheck.value.id)){void router.replace({path:'/lesson',query:{id:pendingCheck.value.id}});}}, {immediate:true});
function begin(id:string){if(props.parent)return;if(pendingCheck.value){go('lesson',{id:pendingCheck.value.id});return;}if(space.value!=='school'||!chapterOf(id))return;if(!scriptedPreview){if(id==='fractions')void beginReal();else notice.value='本轮先开放“分数的应用”，其他章节的真实教学仍在准备。';return;}const s=startLesson(id);go('lesson',{id:s.id});}
watch(()=>[page.value,current.value?.id,current.value?.status],()=>{if(continuingLegacy.value)void beginReal(current.value);},{immediate:true});
function resume(s:Session){if(props.parent||s.space!==space.value||s.learner!==child.value||s.status==='ended')return;touchSession(s);go('lesson',{id:s.id});}
function finish(reason:string){if(props.parent||!current.value||current.value.status==='ended')return;current.value.status='ended';current.value.endedReason=reason;touchSession(current.value);go('result',{id:current.value.id});}
function submit(){if(props.parent||current.value?.status!=='check'||!current.value.answer.trim())return;current.value.submitted=true;finish('检查已提交');}
function showSegment(i:number){const s=current.value;if(props.parent||!s||s.status!=='learning'||i<0||i>2)return;s.shown??=[s.segment];if(!s.shown.includes(i))s.shown.push(i);s.segment=i;touchSession(s);}
function helpToggled(event:Event){if((event.target as HTMLDetailsElement).open&&current.value)current.value.postHelpShown=true;}
function openRecord(r:RecordItem){go('record',{id:r.id,from:route.fullPath});}
function issue(){if(!props.parent||!record.value||!reviewReason.value.trim())return;const row=requestReview(record.value,reviewReason.value.trim());notice.value=`复核事项 ${row.id} 已提交，可在下方查看处理状态。`;reviewReason.value='';reviewOpen.value=false;}
const issues=computed(()=>state.issues.filter(i=>i.learner===child.value&&i.space===space.value&&i.recordId===record.value?.id));
const allRecords=computed(()=>q('kind','questions')==='activities'?[...live.value,...history.value.filter((_,i)=>i%5===0).map(r=>({...r,kind:'活动',title:`${chapterOf(r.chapter)?.name} · 学习活动`}))]:[...live.value.filter(r=>r.answer||r.practice),...history.value]);
const filtered=computed(()=>allRecords.value.filter(r=>(!q('search')||`${r.title} ${r.id}`.includes(q('search')))&&(!q('chapter')||r.chapter===q('chapter'))&&(!q('source')||r.source===q('source'))&&(q('wrong')!=='1'||r.outcome==='错误')).sort((a,b)=>q('sort')==='oldest'?a.date.localeCompare(b.date):b.date.localeCompare(a.date)));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/12)));
const currentPage=computed(()=>Math.max(1,Math.min(Number(q('p','1'))||1,pages.value)));
const rows=computed(()=>filtered.value.slice((currentPage.value-1)*12,currentPage.value*12));
const totalRequirements=()=>chapters.reduce((sum,c)=>sum+c.requirements.length,0);
const counts=(cid:string)=>chapterCounts(cid,child.value,space.value);
const shownStatus=(index:number)=>displayRequirementState(child.value,index,space.value);
</script>
<template><div class="learner-shell" :class="{'student-status-shell':!parent&&['home','status'].includes(page)}"><header v-if="!conversationPage" class="learner-header"><a class="brand" :href="parent?'structure.html?role=parent':'structure.html'">DeerMind<span>{{ parent?'家长':'学习' }}</span></a><div class="context-controls"><label v-if="parent">孩子<select :value="child" @change="selectChild" aria-label="当前孩子"><option value="S0001">林同学</option><option value="S0042">周同学</option></select></label><label><span class="context-caption">学习空间</span><select :value="space" @change="selectSpace" :disabled="!!pendingCheck" aria-label="当前学习空间"><option value="school">校内数学</option><option value="external">校外数学</option></select></label><button class="avatar" @click="go('account')" aria-label="账号与关系">{{ parent?'家':'林' }}</button></div></header>
<nav v-if="!conversationPage" class="learner-nav" aria-label="主导航"><button v-for="[id,label] in nav" :key="id" :class="{active:navActive===id}" @click="go(id!)">{{ label }}</button></nav>
<main ref="mainElement" class="learner-main" :class="{'activity-main':page==='lesson','real-main':conversationPage}">
 <p v-if="notice" class="notice" role="status">{{ notice }}</p>
 <LiveLesson v-if="page==='lesson'&&current?.real" :key="current.id" :session="current" @home="go('home')"/>
 <section v-else-if="continuingLegacy" class="empty"><h1>{{ creatingReal?'正在打开学习对话…':'暂时无法打开对话' }}</h1><p>原预写活动与输入仍保留。</p><button v-if="!creatingReal" @click="beginReal(current)">重新连接</button></section>
 <StudentHome v-else-if="page==='home'&&!parent" :space="space" :scope="scope" @navigate="go" @begin="begin" @resume="resume"/>
 <LearningStatus v-else-if="page==='status'&&!parent" :space="space" :scope="scope" @navigate="go" @begin="begin"/>

 <template v-else-if="page==='materials'"><div class="page-heading"><div><p class="eyebrow">当前采用的教材</p><h1>教材</h1><p class="muted">章节是入口；讲解和检测在选定范围后开始。</p></div></div><div v-if="space==='school'" class="chapter-list"><button v-for="c in chapters" :key="c.id" class="chapter-row" @click="go('chapter',{chapter:c.id})"><span class="chapter-order">{{ c.order }}</span><span><strong>{{ c.name }}</strong><small>{{ c.goal }}</small></span><span class="tag">{{ scriptedPreview?'预写内容可走查':c.id==='fractions'?'可以开始学习':'教学内容准备中' }}</span><span>→</span></button></div><div v-else class="empty"><h2>这套课程的材料尚未就绪</h2><p>准备完成后会显示在这里；两个空间的学习记录独立。</p></div></template>
 <template v-else-if="page==='chapter'&&chapter"><button class="back" @click="go('materials')">← 教材目录</button><div class="page-heading"><div><p class="eyebrow">{{ chapter.order }}</p><h1>{{ chapter.name }}</h1><p class="muted">{{ chapter.goal }}</p></div></div><div v-if="space==='school'" class="two-columns"><section class="panel"><h2>本章学习要求</h2><ul class="plain-list"><li v-for="r in chapter.requirements" :key="r">{{ r }}</li></ul></section><section class="panel"><h2>从这里开始</h2><p>每次讲清一个关键问题，你决定继续、追问或停止。</p><button class="primary" :disabled="creatingReal||(!scriptedPreview&&chapter.id!=='fractions')" @click="begin(chapter.id)">{{ creatingReal?'正在打开…':'开始章节讲解' }}</button><hr/><p class="muted">{{ scriptedPreview?'当前为预写情境，供对照与回归走查。':chapter.id==='fractions'?'进入同一个对话页面，直接讨论、练习和检查理解。':'本轮先开放分数的应用。' }}</p></section></div><p v-else class="empty">当前空间尚未准备本章。</p></template>
 <ConversationLesson v-else-if="page==='lesson'&&current&&currentChapter" :key="current.id" :session="current" :scope="scope" @home="go('home')" @record="openRecord(sessionRecord(current))"/>
 <template v-else-if="page==='prepare'&&current&&current.status==='learning'"><button class="back" @click="go('lesson',{id:current.id})">← 返回讲解</button><div class="page-heading"><div><h1>检查这次理解了什么</h1><p class="muted">{{ currentChapter?.name }} · 1 道合成题 · 参考 3 分钟</p></div></div><section class="panel"><h2>{{ currentChapter?.goal }}</h2><ul><li>保留刚才的讲解背景，这次检查不能单独证明持久掌握。</li><li>需要实质讲解时先结束检查；未作答不会被记成错误。</li><li>本稿只保存作答，不运行评分或更新掌握判断。</li></ul><button class="primary" @click="current.status='check';go('lesson',{id:current.id})">开始检查</button></section></template>
 <template v-else-if="page==='result'&&current"><p class="eyebrow">本次活动结果</p><h1>{{ current.endedReason }}</h1><section class="panel"><h2>{{ currentChapter?.name }}</h2><p>已展开 {{ current.shown?.length||current.segment+1 }} 段讲解；{{ current.submitted?'已提交 1 次作答，尚未判定':'没有提交本次检查作答' }}。</p><h3 v-if="current.answer">{{ current.submitted?'实际提交':'未提交草稿' }}</h3><blockquote v-if="current.answer">{{ current.answer }}</blockquote><p class="muted">本次实际操作单独保留，不改变预写的章节状态。</p><div class="action-bar"><button class="primary" @click="openRecord(sessionRecord(current))">查看这次记录</button><button @click="go('home')">回到首页</button></div><details v-if="current.endedReason.includes('请求讲解')" @toggle="helpToggled"><summary>查看预写帮助</summary><p>{{ currentChapter?.reference }}</p></details></section></template>
 <template v-else-if="page==='overview'||page==='status'"><div class="page-heading"><div><p class="eyebrow">{{ parent?`${learnerName(child)} · `:'' }}{{ spaceName(space) }}</p><h1>{{ parent?'现在学得怎样':'学习情况' }}</h1><p class="muted">先看章节，再看具体要求与判断依据。</p></div></div>
  <ClassroomProgress v-if="parent&&space==='school'" :learner="child" :space="space" :catalog="statusCatalog(3)" readonly/>
  <div v-if="space!=='school'" class="empty"><h2>还没有本空间的学习评价</h2><p>材料尚未就绪。没有记录，不代表不会。</p></div><template v-else><p class="data-note">{{ hasReference(child,space)?'以下章节状态来自预写参考资料 · 截至 2026-10-17':'当前尚无充分评价依据，以下要求均待确认' }} · 共 {{ totalRequirements() }} 项要求，不是能力总分。</p>
  <div class="status-legend"><span>● 已达标</span><span>◐ 需加强</span><span>○ 待确认</span></div><div class="chapter-list"><button v-for="c in chapters" :key="c.id" class="chapter-row" @click="go('status',{chapter:c.id})"><span class="chapter-order">{{ c.order }}</span><span><strong>{{ c.name }}</strong><span v-if="classroomIsCurrent(child,space,c.id)" class="classroom-marker">课堂正在学</span></span><span class="counts"><b v-for="(n,i) in counts(c.id)" :key="i">{{ n }}<small>{{ ['已达标','需加强','待确认'][i] }}</small></b></span><span>→</span></button></div>
  <section v-if="q('chapter')&&chapter" class="panel section-space"><h2>{{ chapter.name }} · 具体要求</h2><div v-for="(r,i) in chapter.requirements" :key="r" class="requirement-row"><div><strong>{{ r }}</strong><span class="tag">{{ shownStatus(i) }}</span><p class="muted small">{{ shownStatus(i)==='待确认'?'当前资料不足以作出稳定判断。':'预写状态仅用于查看布局；这项要求的判断依据尚未准备。' }}</p></div><button v-if="history.some(x=>x.chapter===chapter!.id)" @click="openRecord(history.find(x=>x.chapter===chapter!.id)!)">查看本章记录示例</button></div><button v-if="!parent" @click="begin(chapter.id)">请求本章讲解</button></section>
  <section v-if="live.length" class="section-space"><div class="section-title"><h2>本轮实际学习记录</h2><span class="muted small">未运行评价</span></div><button v-for="r in live.slice(0,5)" :key="r.id" class="record-row" @click="openRecord(r)"><span><strong>{{ chapterOf(r.chapter)?.name }} · {{ r.title }}</strong><small>{{ r.date }} · {{ r.outcome }}</small></span><span>查看 →</span></button></section></template>
 </template>
 <template v-else-if="page==='records'"><div class="page-heading"><div><p class="eyebrow">{{ spaceName(space) }}</p><h1>学习记录</h1><p class="muted">找回一次学习，或查看一道题的历次尝试。</p></div></div><div class="tabs"><button :class="{active:q('kind','questions')==='questions'}" @click="filter('kind','questions')">题目与作答</button><button :class="{active:q('kind')==='activities'}" @click="filter('kind','activities')">学习活动</button></div><div class="filters"><label class="search-field">查找记录<input :value="q('search')" @input="filter('search',($event.target as HTMLInputElement).value)" placeholder="题目文字或记录编号" aria-label="查找记录"/></label><label>章节<select :value="q('chapter')" @change="filter('chapter',($event.target as HTMLSelectElement).value)"><option value="">全部章节</option><option v-for="c in chapters" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label>来源<select :value="q('source')" @change="filter('source',($event.target as HTMLSelectElement).value)"><option value="">全部来源</option><option>讲解练习</option><option>检测</option><option>外部录入</option></select></label><label>排序<select :value="q('sort','newest')" @change="filter('sort',($event.target as HTMLSelectElement).value)"><option value="newest">最近在前</option><option value="oldest">较早在前</option></select></label></div><div class="section-title"><label><input type="checkbox" :checked="q('wrong')==='1'" @change="filter('wrong',($event.target as HTMLInputElement).checked?'1':'')"/> 只看确认错题</label><span class="muted small">{{ filtered.length }} 条 · 包含预写资料与本轮实际提交</span></div><div class="record-list"><button v-for="r in rows" :key="r.id" class="record-row" @click="openRecord(r)"><span><strong>{{ r.title }}</strong><small>{{ r.date||'原作答日期未知' }} · {{ r.source }} · {{ r.id }}</small></span><span class="tag">{{ r.outcome }}</span></button><div v-if="!rows.length" class="empty"><h2>当前条件下没有记录</h2><p>可以更换章节或清除筛选；这不表示没有掌握。</p><button @click="router.replace('/records')">清除筛选</button></div></div><div class="pagination"><span>第 {{ currentPage }} / {{ pages }} 页</span><button :disabled="currentPage===1" @click="router.replace({query:{...route.query,p:currentPage-1}})">上一页</button><button :disabled="currentPage===pages" @click="router.replace({query:{...route.query,p:currentPage+1}})">下一页</button></div></template>
 <template v-else-if="page==='record'&&record"><button class="back" @click="back">← 返回原位置</button><div class="page-heading"><div><p class="eyebrow">{{ chapterOf(record.chapter)?.name }} · {{ record.id }}</p><h1>{{ record.kind==='活动'?'本次学习记录':'题目与作答' }}</h1><p class="muted">{{ record.date||'原作答日期未知' }} · {{ record.source }} · {{ record.outcome }}</p></div></div><section class="panel"><h2>{{ record.title }}</h2><p v-if="record.id.startsWith('R-')" class="data-note">预写资料，用于核对列表与详情；不是本轮新判定。</p><template v-if="record.problem"><h3>本次检查的问题</h3><p>{{ record.problem }}</p></template><h3>当时的作答</h3><blockquote>{{ record.answer||'没有提交作答' }}</blockquote><template v-if="record.practice"><h3>讲解中的练习 · 尚未判定</h3><p>{{ record.practice.problem }}</p><blockquote>{{ record.practice.answer }}</blockquote></template><h3>当时得到的帮助</h3><p>{{ record.help }}</p><p class="muted small">记录、帮助与评价分开。当前页面不会因为看过或答过就改变章节状态。</p></section>
  <div class="action-bar" v-if="!parent"><button v-if="state.sessions.some(s=>s.id===record?.id&&s.real)" class="primary" @click="go('lesson',{id:record.id})">回看真实对话</button><button v-else class="primary" @click="begin(record.chapter)">回到本章讲解</button><button @click="go('status',{chapter:record.chapter})">查看本章学习情况</button></div><section v-else class="section-space"><div class="section-title"><h2>对系统结果有疑问？</h2><button @click="reviewOpen=!reviewOpen">提出复核</button></div><p class="muted">可以先咨询原因；需要处理时明确提交。家长不能在这里修改孩子的作答。</p><form v-if="reviewOpen" class="panel" @submit.prevent="issue"><label class="field">希望核对什么<textarea v-model="reviewReason" rows="3" aria-label="复核说明" placeholder="说明预期与看到的结果有什么差异…"/></label><p class="muted small">仅附本记录与当前孩子、空间，私人咨询不会自动全部转交。</p><button class="primary" :disabled="!reviewReason.trim()">提交复核事项</button></form><article v-for="i in issues" :key="i.id" class="panel"><span class="tag">{{ i.status }}</span><p>{{ i.reason }}</p><p v-if="i.note">处理意见：{{ i.note }}</p><small>{{ i.id }}</small></article></section></template>
 <template v-else-if="page==='consult'&&parent"><p class="eyebrow">{{ learnerName(child) }} · {{ spaceName(space) }}</p><h1>和 DeerMind 商量</h1><p class="lead">你想了解哪一部分，或想怎样帮助孩子？</p><section class="panel"><h2>这段咨询只属于你</h2><p>可以从概况或某条依据开始问，也可以直接输入观察到的情况。</p><p class="muted">咨询不会成为孩子的作答，不会向孩子或其他家长展示。需要复核某条结果时，在那条记录上明确提交。</p><button @click="go('overview')">查看孩子的学习情况</button></section></template>
 <template v-else-if="page==='account'"><h1>账号与关系</h1><section class="panel"><h2>{{ parent?'演示家长':learnerName(child) }}</h2><p>当前为独立低保真资料，无真实账号认证。</p><p>{{ parent?'已关联：林同学、周同学。可切换查看，不能修改孩子资料。':'校内与校外学习空间分别保存记录。' }}</p><p class="muted">开户、找回、首次告知和空间创建沿用已确认规则；本轮未展开这些画面。</p><button @click="go(parent?'overview':'home')">返回</button></section></template>
 <div v-else class="empty"><h1>当前范围内没有这条内容</h1><p>它可能不属于当前孩子或学习空间，也可能已失效。</p><button @click="go(parent?'overview':'home')">回到当前空间</button></div>
</main><Composer v-if="!conversationPage" :scope="scope" :inline="page==='lesson'&&!parent" :checking="page==='lesson'&&current?.status==='check'" :context="`${parent?learnerName(child)+' · ':''}${spaceName(space)}${currentChapter?' · '+currentChapter.name:page==='status'&&q('chapter')&&chapter?' · '+chapter.name:''}`" :parent="parent" :home="['home','status'].includes(page)&&!parent"/></div></template>

<style scoped>.learner-main.real-main{padding:0;overflow:hidden;display:flex;flex-direction:column;max-width:none;background:#f7f8fa}.real-main>.live-workspace{flex:1;max-width:1120px;width:100%;margin:0 auto}.real-main>.notice{margin:16px 24px}</style>
